const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>{const p={home:'<path d="m3 10 9-7 9 7v10H3zM9 20v-6h6v6"/>',map:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m3 15 5-5 4 4 3-3 6 5M8 8h.01"/>',ruler:'<path d="M4 20 20 4M7 5l2 2M5 9l2 2M11 13l2 2M15 17l2 2"/>',layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 3v2M21 12h-2M12 21v-2M3 12h2"/>',chat:'<path d="M4 4h16v12H9l-5 4zM8 8h8M8 11h5"/>',network:'<circle cx="5" cy="12" r="2.5"/><circle cx="19" cy="6" r="2.5"/><circle cx="19" cy="18" r="2.5"/><path d="m7.3 11 9.4-4M7.3 13l9.4 4"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[n]||p.home}</svg>`};
const nav=[['home','overview','Overview'],['map','scenario','Design scenario'],['ruler','estimate','Estimate scale'],['layers','architecture','Architecture board'],['network','network','Network essentials'],['target','tradeoffs','Tradeoffs'],['chat','rehearse','Rehearse']];
const missions=[
 {title:'Clarify before drawing',desc:'Ask about users, core actions, freshness, availability, and the failure that matters most.',view:'scenario',time:'8 min'},
 {title:'Estimate the shape',desc:'Turn users and request rates into rough bandwidth, storage, and replica numbers.',view:'estimate',time:'12 min'},
 {title:'Draw the first useful architecture',desc:'Place a gateway, service, queue, datastore, cache, and observability boundary.',view:'architecture',time:'14 min'},
 {title:'Choose the right reliability tool',desc:'Compare timeout, retry, idempotency, queue, circuit breaker, and dead-letter choices.',view:'tradeoffs',time:'14 min'},
 {title:'Defend a tradeoff',desc:'Practice saying what you optimize, what you give up, and how you would validate it.',view:'tradeoffs',time:'10 min'},
 {title:'Give the interview answer',desc:'Use a repeatable six-part structure under a visible timer.',view:'rehearse',time:'15 min'}
];
const scenarios=[
 {title:'Real-time drone track fan-out',tag:'integration engineer',prompt:'Sensors produce tracks. Multiple customer C2 systems need updates. Design the path from ingestion to customer display.',users:'Operators and C2 clients',actions:'Publish, query snapshot, acknowledge health',freshness:'under 2 seconds',risk:'stale or duplicated tracks'},
 {title:'Webhook ingestion platform',tag:'REST + events',prompt:'Many partners send webhooks. Your service validates, deduplicates, transforms, and forwards them to internal consumers.',users:'External partners and internal teams',actions:'Accept, inspect status, replay failed events',freshness:'under 30 seconds',risk:'duplicate side effects'},
 {title:'Multi-tenant orders API',tag:'backend service',prompt:'Customers create and read orders. Traffic grows from 20 to 2,000 requests per second during promotions.',users:'Customers and support agents',actions:'Create, list, update, cancel',freshness:'read-after-write for own order',risk:'tenant data leakage'},
 {title:'Field deployment telemetry',tag:'intermittent networks',prompt:'A deployed system sends telemetry over unreliable links to an operations center with a map and archive.',users:'Field operators and analysts',actions:'Stream, snapshot, replay, inspect link health',freshness:'latest state over history',risk:'offline backlog and clock skew'}
];
const tradeoffs=[
 {title:'Queue or direct call?',prompt:'A customer endpoint is slow and occasionally offline. What should sit between your core service and that destination?',choices:['A bounded per-destination queue with retry and visible lag','An unbounded in-memory queue','Block every sensor request until the customer responds'],answer:0,why:'A bounded queue isolates the failure and gives you a place to measure lag. Decide what to drop, coalesce, or persist based on the data’s meaning.'},
 {title:'Cache or database?',prompt:'A read-heavy endpoint serves mostly unchanged configuration for five minutes. What is the natural first tool?',choices:['A cache with an explicit TTL and invalidation story','Write every read to a new database row','A queue with no consumer'],answer:0,why:'Caching reduces repeated work, but correctness depends on TTL, invalidation, scope, and what stale data is acceptable.'},
 {title:'Retry or reject?',prompt:'The API responds 422 with a missing required field. What should the integration do?',choices:['Reject, record the validation details, and fix the contract or mapping','Retry the same payload until it works','Hide the error and mark the operation successful'],answer:0,why:'A permanent validation failure will not improve through retry. Preserve the evidence and keep success truthful.'},
 {title:'Partition what?',prompt:'You need to preserve order for each track while processing many tracks concurrently. What is a reasonable partition key?',choices:['Source + track ID, with independent work per key','One global lock for every message','Random partitioning with no sequence check'],answer:0,why:'Partitioning by the identity whose order matters gives concurrency across keys and ordering within a key.'}
];
let route='overview',mission=0,scenario=0,done=JSON.parse(localStorage.getItem('systemforge-done')||'[]'),assumptions=JSON.parse(localStorage.getItem('systemforge-assumptions')||'{}'),tradeoff=0,choice=null,result='',framework='outline',timer=null,seconds=900;
function save(){localStorage.setItem('systemforge-done',JSON.stringify(done));localStorage.setItem('systemforge-assumptions',JSON.stringify(assumptions))}
function mark(i){if(!done.includes(i)){done.push(i);save()}}
function toast(t){document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.textContent=t;document.body.append(d);setTimeout(()=>d.remove(),4000)}
function layout(){const n=nav.find(x=>x[1]===route)||nav[0];document.querySelector('#app').innerHTML=`<div class="shell"><aside class="side"><div class="logo"><span class="mark">S∕</span> SystemForge</div><div class="side-label">System design interview lab</div><nav class="nav">${nav.map(([ic,id,label],i)=>`<button data-nav="${id}" class="${route===id?'active':''}">${icon(ic)}<span>${label}</span><span class="num">0${i+1}</span></button>`).join('')}</nav><div class="side-bottom"><div class="eyebrow">Interview path</div><div class="meter"><i style="width:${Math.round(done.length/missions.length*100)}%"></i></div><span style="font-size:.76rem;color:#9aa6b4">${done.length} / ${missions.length} missions complete</span><p>Clarify → estimate → design → defend.</p></div></aside><main class="main"><header class="top"><span class="crumb">Workspace &nbsp;/&nbsp; <b>${n[2]}</b></span><span class="live">● PRACTICE MODE</span></header><div class="content" id="page"></div></main></div>`;renderPage()}
function intro(title,sub,actions=''){return `<div class="intro"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function stat(label,value,small){return `<div class="stat"><label>${label}</label><strong>${value}</strong><small>${small}</small></div>`}
function overview(){return intro('Think in systems','A calm, repeatable playground for system-design interviews. Start with a problem, then earn the architecture.',`<button class="primary" data-action="start">Start a design →</button>`)+`<div class="grid-stats">${stat('Missions',`${done.length} / ${missions.length}`,'Saved in this browser')}${stat('Practice scenarios',scenarios.length,'Drone, webhook, orders, field')}${stat('Estimation inputs','6','Users, rates, payload, retention')}${stat('Answer timer','15:00','Rehearse out loud')}</div><div class="layout"><div class="panel"><div class="panel-head"><h2>Interview path</h2><span class="badge green">SIX MOVES</span></div><div class="panel-body"><div class="mission-list">${missions.map((m,i)=>`<button class="mission" data-mission="${i}"><span class="n">${done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${m.title}</strong><small>${m.desc}<br>${m.time}</small></span></button>`).join('')}</div></div></div><aside class="panel side-card"><span class="badge orange">START HERE</span><h2>System design is a conversation.</h2><p>The interviewer is looking for how you make uncertainty visible, choose boundaries, and explain tradeoffs.</p><ol><li>Clarify the user and the success condition.</li><li>Estimate before choosing infrastructure.</li><li>Draw one simple architecture.</li><li>Walk through failure and scale.</li></ol><button class="primary" data-action="start" style="width:100%">Open design scenario</button><div class="callout"><strong>Interview phrase:</strong> “I’ll state assumptions, do a rough capacity estimate, then choose the simplest architecture that meets the stated reliability and latency goals.”</div></aside></div><div class="flow"><div class="flow-node"><b>01 · CLARIFY</b><small>users + constraints</small></div><span class="flow-arrow">→</span><div class="flow-node"><b>02 · ESTIMATE</b><small>rate + storage</small></div><span class="flow-arrow">→</span><div class="flow-node"><b>03 · DESIGN</b><small>boundaries + flow</small></div><span class="flow-arrow">→</span><div class="flow-node"><b>04 · DEFEND</b><small>failure + tradeoff</small></div></div>`}
function scenarioPage(){const s=scenarios[scenario];return intro('Design the problem first','Pick a scenario and write down the assumptions you would ask about before drawing boxes.',`<span class="badge orange">MISSION 01</span>`)+`<div class="columns"><div class="panel"><div class="panel-head"><h2>Scenario cards</h2><span class="glance">${scenario+1} / ${scenarios.length}</span></div><div class="panel-body"><div class="scenario-nav">${scenarios.map((x,i)=>`<button data-scenario="${i}" class="${scenario===i?'active':''}"><span class="tag">${x.tag}</span><br>${x.title}</button>`).join('')}</div></div></div><article class="panel concept"><span class="badge green">${s.tag.toUpperCase()}</span><h2>${s.title}</h2><p>${s.prompt}</p><div class="mini-grid"><div class="mini"><span>Primary users</span><b>${s.users}</b></div><div class="mini"><span>Core actions</span><b>${s.actions}</b></div><div class="mini"><span>Freshness goal</span><b>${s.freshness}</b></div><div class="mini"><span>Biggest risk</span><b>${s.risk}</b></div></div><label class="field" for="assumptions">Your assumptions and clarifying questions</label><textarea id="assumptions" rows="9" placeholder="Who writes? How many users? What does success mean? What can be stale? What must never happen?">${esc(assumptions[scenario]||'')}</textarea><div class="actions" style="margin-top:15px"><button class="primary" data-action="save-assumptions">Save assumptions and continue →</button><button data-action="next-scenario">Next scenario</button></div><div class="callout"><strong>Good questions are architectural inputs.</strong> Ask about throughput, latency, availability, consistency, retention, security boundaries, and what happens when a dependency is down.</div></article></div>`}
function estimatePage(){const v={users:Number(assumptions.users||10000),actions:Number(assumptions.actions||4),peak:Number(assumptions.peak||200),payload:Number(assumptions.payload||2),retention:Number(assumptions.retention||7),availability:Number(assumptions.availability||99.9)};const avg=v.peak/10,day=v.peak*86400,gb=(day*v.payload*1.3/1024/1024).toFixed(1),replicas=Math.max(2,Math.ceil(v.peak/120));return intro('Estimate the shape','Rough numbers keep the design grounded. Precision is less valuable than visible assumptions.',`<button data-action="save-estimate">Save estimate</button><span class="badge green">BACK-OF-THE-ENVELOPE</span>`)+`<div class="layout"><div class="panel"><div class="panel-head"><h2>Capacity inputs</h2><span class="glance">Change a number and recalculate</span></div><div class="panel-body"><div class="estimate-grid"><div class="field"><label for="users">Active users / day</label><input id="users" type="number" min="1" value="${v.users}"></div><div class="field"><label for="actions">Actions per user / day</label><input id="actions" type="number" min="1" value="${v.actions}"></div><div class="field"><label for="peak">Peak requests / second</label><input id="peak" type="number" min="1" value="${v.peak}"></div><div class="field"><label for="payload">Average payload KB</label><input id="payload" type="number" min=".1" step=".1" value="${v.payload}"></div><div class="field"><label for="retention">Retention days</label><input id="retention" type="number" min="1" value="${v.retention}"></div><div class="field"><label for="availability">Availability target %</label><input id="availability" type="number" min="90" max="99.999" step=".001" value="${v.availability}"></div></div><div class="estimate-result"><div class="mini"><span>Daily requests</span><b id="daily">${day.toLocaleString()}</b></div><div class="mini"><span>Peak bandwidth</span><b id="bandwidth">${(v.peak*v.payload*8/1024).toFixed(1)} Mbps</b></div><div class="mini"><span>Daily storage ×1.3</span><b id="storage">${gb} GB</b></div><div class="mini"><span>App replicas @120 rps</span><b id="replicas">${replicas}</b></div><div class="mini"><span>Monthly downtime budget</span><b id="downtime">${((1-v.availability/100)*30*24*60).toFixed(1)} min</b></div><div class="mini"><span>Average rps</span><b id="avg">${avg.toFixed(1)}</b></div></div><div class="callout"><strong>Say the caveat:</strong> “These are order-of-magnitude estimates. I would validate them with production traffic, payload distribution, burst shape, and a load test.”</div></div></div><aside class="panel side-card"><span class="badge">WHY THIS MATTERS</span><h2>Numbers create boundaries.</h2><p>Peak rate influences concurrency and replicas. Payload size influences bandwidth and storage. Retention influences the data model and tiering plan. Availability changes the operational design.</p><div class="tip"><code>daily = peak rps × 86,400</code><br><code>bandwidth ≈ rps × payload × 8</code><br><code>storage ≈ daily bytes × overhead</code></div></aside></div>`}
function architecturePage(){const nodes=[['clients','Clients','browser / C2'],['gateway','API gateway','TLS · auth · rate'],['service','Core service','validate · domain'],['queue','Event queue','buffer · fan-out'],['data','Primary store','durable state'],['cache','Cache','hot reads'],['observe','Telemetry','logs · metrics']];return intro('Draw the first useful architecture','Place boundaries where they help you explain ownership, failure, and scale.',`<button class="primary" data-action="complete-architecture">Mark mission complete</button>`)+`<div class="panel"><div class="panel-head"><h2>Architecture board</h2><span class="badge green">CLICKABLE COMPONENTS</span></div><div class="architecture"><div class="arch-label">SYSTEMFORGE / ${esc(scenarios[scenario].title).toUpperCase()}</div><svg viewBox="0 0 980 480" role="img" aria-label="System architecture diagram"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0 0 8 3 0 6Z" fill="#718092"/></marker></defs><path d="M140 239h110m150 0h110m150 0h120M420 239v-100h90M420 239v100h90M670 239v-100h90M670 239v100h90" stroke="#718092" stroke-width="2" fill="none" marker-end="url(#arrow)"/><g id="arch-nodes">${nodes.map((n,i)=>{const pos=[[35,205],[250,205],[420,205],[570,205],[760,90],[760,205],[760,320]][i];return `<g data-arch="${n[0]}" transform="translate(${pos[0]} ${pos[1]})" tabindex="0" role="button"><rect width="140" height="68" rx="8" fill="${i===3?'#362b23':'#202833'}" stroke="${i===3?'#a2673e':'#4b5d6e'}"/><text x="70" y="28" text-anchor="middle" fill="${i===3?'#f0b768':'#e8edf1'}" font-family="DM Sans" font-size="14" font-weight="600">${n[1]}</text><text x="70" y="48" text-anchor="middle" fill="#96a3b2" font-family="IBM Plex Mono" font-size="9">${n[2]}</text></g>`}).join('')}</g></svg><div class="legend"><span>core boundary</span><span>service dependency</span><span>selected queue</span></div></div></div><div class="columns" style="margin-top:19px"><div class="panel concept"><span class="tag">WALK THE FLOW</span><h2>Request path</h2><p>Client → gateway → core service → primary store. Add cache only for proven hot reads. Add a queue when you need asynchronous work, fan-out, buffering, or a durable handoff.</p><div id="arch-detail" class="tip">Click a component to see its interview explanation.</div></div><div class="panel concept"><span class="tag">BOUNDARIES</span><h2>What can fail?</h2><p>Make each boundary observable: request ID, status, latency, queue depth, consumer lag, database errors, cache hit ratio, and dependency health. Design the fallback before the outage.</p><div class="tip">A box is not an architecture until you can explain ownership, data flow, failure, and recovery.</div></div></div>`}
function networkPage(){return window.SystemForgeNetwork.render();}
function tradeoffsPage(){const t=tradeoffs[tradeoff];return intro('Defend the tradeoff','The strongest answer is specific about the property you protect and the cost you accept.',`<span class="badge orange">SCENARIO ${tradeoff+1} / ${tradeoffs.length}</span>`)+`<div class="challenge-layout" style="display:grid;grid-template-columns:250px 1fr;gap:19px"><div class="scenario-nav">${tradeoffs.map((x,i)=>`<button data-tradeoff="${i}" class="${i===tradeoff?'active':''}">${String(i+1).padStart(2,'0')} · ${x.title}</button>`).join('')}</div><article class="panel scenario"><span class="tag">TRADEOFF</span><h2>${t.title}</h2><p>${t.prompt}</p>${t.choices.map((c,i)=>`<label class="option"><input type="radio" name="trade" value="${i}" ${choice===i?'checked':''}>${c}</label>`).join('')}<button class="primary" data-action="check-trade">Check decision</button>${result?`<div class="${result==='correct'?'success':'error'}">${result==='correct'?'Correct. ':''}${result==='correct'?t.why:'Look for the choice that preserves the important safety or reliability property and leaves evidence.'}</div>`:''}<div class="callout"><strong>Interview structure:</strong> “Given X, I choose Y because it protects Z. The tradeoff is W. I would validate it with Q.”</div></article></div>`}
function rehearsePage(){const mins=Math.floor(seconds/60),secs=String(seconds%60).padStart(2,'0');return intro('Rehearse the answer','Use the same sequence every time so your explanation stays clear under pressure.',`<button class="primary" data-action="timer">${timer?'Pause':'Start'} ${mins}:${secs}</button><span class="badge green">${framework==='outline'?'ANSWER OUTLINE':'PROMPT CARD'}</span>`)+`<div class="columns"><div class="panel concept"><span class="tag">SIX PARTS</span><h2>System-design answer template</h2><ol><li><strong>Clarify.</strong> Users, core actions, scope, success.</li><li><strong>Constraints.</strong> Rate, latency, availability, consistency, retention.</li><li><strong>Estimate.</strong> Rough traffic, storage, bandwidth, concurrency.</li><li><strong>Design.</strong> API, data model, components, flow.</li><li><strong>Stress it.</strong> Failure, scale, security, observability.</li><li><strong>Trade off.</strong> What you chose, what you gave up, how you validate.</li></ol><button data-action="complete-rehearse">Mark rehearsal complete</button></div><div class="panel concept"><div class="tabs">${[['outline','Outline'],['prompt','Prompt card']].map(([k,l])=>`<button data-rehearse="${k}" class="${framework===k?'active':''}">${l}</button>`).join('')}</div>${framework==='outline'?`<p class="tip">“I’ll assume 10,000 active users, a 200 rps peak, and a 2-second freshness target. I’ll start with an authenticated gateway and a stateless service, persist durable state, and add a bounded queue for asynchronous fan-out. I’ll monitor latency, errors, queue lag, and dependency health. If the scale or availability target changes, I would revisit the datastore, partitioning, and redundancy choices.”</p>`:`<div class="tip"><strong>Prompt:</strong><br>Design a service that receives drone tracks and fans them out to three customer C2 platforms. Explain the API, canonical data model, message delivery, stale data policy, failure isolation, and test plan.</div>`}<label class="field" for="answer">Your spoken answer notes</label><textarea id="answer" rows="10" placeholder="Write the points you want to say aloud…"></textarea><div class="callout"><strong>Do not bluff.</strong> If you have not used a technology, describe the interface specification, a small test harness, the failure cases, and the evidence you would need.</div></div></div>`}
function renderPage(){const f={overview,scenario:scenarioPage,estimate:estimatePage,architecture:architecturePage,network:networkPage,tradeoffs:tradeoffsPage,rehearse:rehearsePage}[route]||overview;document.querySelector('#page').innerHTML=f()+`<div class="foot"><span>SystemForge / system design interview practice</span><span>Scenarios are simulated · Progress stays in this browser</span></div>`;if(route==='overview')document.querySelector('#page').insertAdjacentHTML('afterbegin','<div class="network-invite"><strong>New: Network & cloud essentials</strong><span>DNS, TCP/IP, WebSockets, APIs, load balancers, AWS, and reliability—with diagrams.</span><button data-nav="network" class="primary">Explore the 10 lessons →</button></div>');}
function calc(){const get=id=>Number(document.querySelector('#'+id)?.value||0);const peak=get('peak'),payload=get('payload'),avail=get('availability'),day=peak*86400;document.querySelector('#daily').textContent=day.toLocaleString();document.querySelector('#bandwidth').textContent=(peak*payload*8/1024).toFixed(1)+' Mbps';document.querySelector('#storage').textContent=(day*payload*1.3/1024/1024).toFixed(1)+' GB';document.querySelector('#replicas').textContent=Math.max(2,Math.ceil(peak/120));document.querySelector('#downtime').textContent=((1-avail/100)*30*24*60).toFixed(1)+' min';document.querySelector('#avg').textContent=(peak/10).toFixed(1)}
document.addEventListener('click',e=>{const b=e.target.closest('button');const g=e.target.closest('[data-arch]');if(g){const names={clients:'Clients ask for the system’s behavior. Clarify who calls, what they need, and what response they expect.',gateway:'The gateway terminates TLS, authenticates, rate-limits, adds correlation IDs, and routes. It should not hide domain errors.',service:'Keep domain validation and business decisions here. Stateless services are easier to scale horizontally.',queue:'A queue creates an asynchronous boundary. Bound it, measure lag, define ordering, and decide what happens when it fills.',data:'Durable state needs a data model, indexes, consistency choices, backup, and a migration story.',cache:'A cache is a performance tool with a correctness policy: TTL, invalidation, scope, and acceptable staleness.',observe:'Logs, metrics, traces, health checks, and alerts turn “it is slow” into evidence.'};const d=document.querySelector('#arch-detail');if(d)d.innerHTML=`<strong>${g.dataset.arch}</strong><br>${names[g.dataset.arch]}`;return}if(!b)return;if(b.dataset.nav){route=b.dataset.nav;history.replaceState(null,'','#'+route);renderPage();document.querySelector('.crumb b').textContent=nav.find(n=>n[1]===route)?.[2]||'';document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===route));return}if(b.dataset.mission!==undefined){mission=Number(b.dataset.mission);const m=missions[mission];route=m.view;mark(mission);layout();return}if(b.dataset.scenario!==undefined){scenario=Number(b.dataset.scenario);renderPage();return}if(b.dataset.tradeoff!==undefined){tradeoff=Number(b.dataset.tradeoff);choice=null;result='';renderPage();return}if(b.dataset.rehearse){framework=b.dataset.rehearse;renderPage();return}switch(b.dataset.action){case'start':route='scenario';layout();break;case'save-assumptions':assumptions[scenario]=document.querySelector('#assumptions').value;save();mark(0);toast('Assumptions saved. Now estimate the scale.');break;case'next-scenario':scenario=(scenario+1)%scenarios.length;renderPage();break;case'save-estimate':assumptions.users=document.querySelector('#users').value;assumptions.actions=document.querySelector('#actions').value;assumptions.peak=document.querySelector('#peak').value;assumptions.payload=document.querySelector('#payload').value;assumptions.retention=document.querySelector('#retention').value;assumptions.availability=document.querySelector('#availability').value;save();mark(1);toast('Estimate saved. Use it to justify your architecture.');break;case'complete-architecture':mark(2);toast('Architecture mission complete. Continue to tradeoffs.');break;case'check-trade':{const c=document.querySelector('input[name="trade"]:checked');if(!c){toast('Choose a decision first.');break}choice=Number(c.value);result=choice===tradeoffs[tradeoff].answer?'correct':'try';if(result==='correct'){mark(3);toast('Good tradeoff reasoning.')}renderPage();break}case'complete-rehearse':mark(5);toast('Rehearsal logged. Say the answer out loud once more.');break;case'timer':if(timer){clearInterval(timer);timer=null}else{timer=setInterval(()=>{if(seconds>0){seconds--;const b=document.querySelector('[data-action="timer"]');if(b)b.textContent=`Pause ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}else{clearInterval(timer);timer=null;toast('Time. Finish your tradeoff statement.')}},1000)}break}});
document.addEventListener('input',e=>{if(['users','actions','peak','payload','retention','availability'].includes(e.target.id))calc();if(e.target.id==='answer')assumptions.answer=e.target.value;});
if(nav.some(item=>item[1]===location.hash.slice(1)))route=location.hash.slice(1);
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(nav.some(item=>item[1]===target)){route=target;layout();}});
layout();
